typedef enum {
	ESL_POLL_READ = (1 << 0),
	ESL_POLL_WRITE = (1 << 1),
	ESL_POLL_ERROR = (1 << 2)
} esl_poll_t;

typedef enum {
	ESL_EVENT_TYPE_PLAIN,
	ESL_EVENT_TYPE_XML,
	ESL_EVENT_TYPE_JSON
} esl_event_type_t;

typedef enum {
	ESL_SUCCESS,
	ESL_FAIL,
	ESL_BREAK,
	ESL_DISCONNECTED,
	ESL_GENERR
} esl_status_t;

typedef struct {
	struct sockaddr_storage sockaddr;
	struct hostent hostent;
	char hostbuf[256];
	esl_socket_t sock;
	char err[256];
	int errnum;
	esl_buffer_t *packet_buf;
	char socket_buf[65536];
	char last_reply[1024];
	char last_sr_reply[1024];
	esl_event_t *last_event;
	esl_event_t *last_sr_event;
	esl_event_t *race_event;
	esl_event_t *last_ievent;
	esl_event_t *info_event;
	int connected;
	struct sockaddr_in addr;
	esl_mutex_t *mutex;
	int async_execute;
	int event_lock;
	int destroyed;
} esl_handle_t;

typedef enum {
	ESL_TRUE = 1,
	ESL_FALSE = 0
} esl_bool_t;

typedef enum {
	ESL_STACK_BOTTOM,
	ESL_STACK_TOP,
	ESL_STACK_PUSH,
	ESL_STACK_UNSHIFT
} esl_stack_t;

typedef enum {
	ESL_PRIORITY_NORMAL,
	ESL_PRIORITY_LOW,
	ESL_PRIORITY_HIGH
} esl_priority_t;

	struct esl_event_header {
	/*! the header name */
	char *name;
	/*! the header value */
	char *value;
	/*! array space */
	char **array;
	/*! array index */
	int idx;
	/*! hash of the header name */
	unsigned long hash;
	struct esl_event_header *next;
};

struct esl_event {
	/*! the event id (descriptor) */
	esl_event_types_t event_id;
	/*! the priority of the event */
	esl_priority_t priority;
	/*! the owner of the event */
	char *owner;
	/*! the subclass of the event */
	char *subclass_name;
	/*! the event headers */
	esl_event_header_t *headers;
	/*! the event headers tail pointer */
	esl_event_header_t *last_header;
	/*! the body of the event */
	char *body;
	/*! user data from the subclass provider */
	void *bind_user_data;
	/*! user data from the event sender */
	void *event_user_data;
	/*! unique key */
	unsigned long key;
	struct esl_event *next;
	int flags;
};

typedef enum {
	ESL_EF_UNIQ_HEADERS = (1 << 0)
} esl_event_flag_t;

typedef struct cJSON
{
    /* next/prev allow you to walk array/object chains. Alternatively, use GetArraySize/GetArrayItem/GetObjectItem */
    struct cJSON *next;
    struct cJSON *prev;
    /* An array or object item will have a child pointer pointing to a chain of the items in the array/object. */
    struct cJSON *child;

    /* The type of the item, as above. */
    int type;

    /* The item's string, if type==cJSON_String  and type == cJSON_Raw */
    char *valuestring;
    /* writing to valueint is DEPRECATED, use cJSON_SetNumberValue instead */
    int valueint;
    /* The item's number, if type==cJSON_Number */
    double valuedouble;

    /* The item's name string, if this item is the child of, or is in the list of subitems of an object. */
    char *string;
} cJSON;

typedef struct cJSON_Hooks
{
      /* malloc/free are CDECL on Windows regardless of the default calling convention of the compiler, so ensure the hooks allow passing those functions directly. */
      void *(CJSON_CDECL *malloc_fn)(size_t sz);
      void (CJSON_CDECL *free_fn)(void *ptr);
} cJSON_Hooks;

typedef struct esl_config esl_config_t;

/*! \brief A simple file handle representing an open configuration file **/
struct esl_config {
	/*! FILE stream buffer to the opened file */
	FILE *file;
	/*! path to the file */
	char path[1024];
	/*! current category */
	char category[256];
	/*! current section */
	char section[256];
	/*! buffer of current line being read */
	char buf[1024];
	/*! current line number in file */
	int lineno;
	/*! current category number in file */
	int catno;
	/*! current section number in file */
	int sectno;

	int lockto;
};

class ESLevent {
 private:
	esl_event_header_t *hp;
 public:
	esl_event_t *event;
	char *serialized_string;
	int mine;

	ESLevent(const char *type, const char *subclass_name = NULL);
	ESLevent(esl_event_t *wrap_me, int free_me = 0);
	ESLevent(ESLevent *me);
	virtual ~ESLevent();
	const char *serialize(const char *format = NULL);
	bool setPriority(esl_priority_t priority = ESL_PRIORITY_NORMAL);
	const char *getHeader(const char *header_name, int idx = -1);
	char *getBody(void);
	const char *getType(void);
	bool addBody(const char *value);
	bool addHeader(const char *header_name, const char *value);
	bool pushHeader(const char *header_name, const char *value);
	bool unshiftHeader(const char *header_name, const char *value);
	bool delHeader(const char *header_name);
	const char *firstHeader(void);
	const char *nextHeader(void);
};

class ESLconnection {
 private:
	esl_handle_t handle;
 public:
	ESLconnection(const char *host, const int port, const char *user, const char *password);
	ESLconnection(const char *host, const int port, const char *password);
	ESLconnection(const char *host, const char *port, const char *user, const char *password);
	ESLconnection(const char *host, const char *port, const char *password);
	ESLconnection(int socket);
	virtual ~ESLconnection();
	int socketDescriptor();
	int connected();
	ESLevent *getInfo();
	int send(const char *cmd);
	ESLevent *sendRecv(const char *cmd);
	ESLevent *api(const char *cmd, const char *arg = NULL);
	ESLevent *bgapi(const char *cmd, const char *arg = NULL, const char *job_uuid = NULL);
	ESLevent *sendEvent(ESLevent *send_me);
	int sendMSG(ESLevent *send_me, const char *uuid = NULL);
	ESLevent *recvEvent();
	ESLevent *recvEventTimed(int ms);
	ESLevent *filter(const char *header, const char *value);
	int events(const char *etype, const char *value);
	ESLevent *execute(const char *app, const char *arg = NULL, const char *uuid = NULL);
	ESLevent *executeAsync(const char *app, const char *arg = NULL, const char *uuid = NULL);
	int setAsyncExecute(const char *val);
	int setEventLock(const char *val);
	int disconnect(void);
};

